package pro.aanba.tv;
import org.junit.Test;
import static org.junit.Assert.*;
public class PublicLinksTest {
 @Test public void onlyFixedChannelAndActualVideoIdsCanLeaveApp(){assertTrue(SafeLinks.youtube(SafeLinks.YOUTUBE_CHANNEL));assertTrue(SafeLinks.youtube("https://www.youtube.com/watch?v=g68Rh2qeuf4"));for(String url:new String[]{"https://www.youtube.com.evil.example/watch?v=g68Rh2qeuf4","https://www.youtube.com/watch?v=g68Rh2qeuf4&redirect=bad","javascript:alert(1)","file:///etc/passwd","https://www.youtube.com/@another"})assertFalse(url,SafeLinks.youtube(url));}
 @Test public void thumbnailHostCannotBeSpoofed(){assertTrue(SafeLinks.thumbnail("https://i4.ytimg.com/vi/g68Rh2qeuf4/hqdefault.jpg"));for(String url:new String[]{"https://evilytimg.com/vi/g68Rh2qeuf4/hqdefault.jpg","https://i.ytimg.com.evil.example/vi/g68Rh2qeuf4/hqdefault.jpg","http://i.ytimg.com/vi/g68Rh2qeuf4/hqdefault.jpg","https://u:p@i.ytimg.com/vi/g68Rh2qeuf4/hqdefault.jpg","https://i.ytimg.com:1234/vi/g68Rh2qeuf4/hqdefault.jpg"})assertFalse(url,SafeLinks.thumbnail(url));}
 @Test public void sourceRedirectsCannotReachPrivateHostsOrCleartext(){for(String url:new String[]{"https://aanba.pro/schedule","https://site.api.espn.com/apis/scoreboard","https://www.youtube.com/feeds/videos.xml"})assertTrue(SafeLinks.api(url));for(String url:new String[]{"http://aanba.pro/schedule","https://127.0.0.1/","https://localhost/","https://example.com/","https://aanba.pro.evil.example/","https://user:pass@aanba.pro/"})assertFalse(url,SafeLinks.api(url));}
 @Test public void bundledPicksArePublicVideosWithRealTitles()throws Exception{String json=new String(getClass().getResourceAsStream("/youtube-picks.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);YoutubeFeed feed=YoutubeFeed.bundled(json);assertEquals(3,feed.videos.size());for(YoutubeFeed.Video v:feed.videos){assertTrue(SafeLinks.youtube(v.watchUrl()));assertTrue(SafeLinks.thumbnail(v.thumbnail));assertFalse(v.title.isEmpty());assertTrue(v.published>0);}}
}
